 const rows=[['Revenue','revenue'],['Cost of revenue','cost'],['Research & development','research'],['Selling, general & administrative','selling'],['Selling & marketing','sellingMarketing'],['Sales & marketing · reported scope','marketing'],['General & administrative','generalAdmin'],['Operating income','operating'],['Net income','net'],['Income available to common shareholders','commonIncome'],['Pretax income','pretax'],['Income tax expense','incomeTax'],['Operating cash flow','cfo'],['Gross cash equipment purchases','capex'],['Equipment & intangible purchases · reported scope','equipmentIntangiblePurchases'],['Diluted EPS (USD)','eps'],['Dividends paid (see source scope)','dividends'],['Stock-based compensation','sbc'],['Cash & equivalents','cash'],['Short-term investments','investments'],['Current portion of long-term debt','debtCurrent'],['Long-term debt, noncurrent','debtLong'],['Short-term borrowings / commercial paper','shortDebt'],['Common shares outstanding (billions)','shares']];
 $('history-table').innerHTML='<thead><tr><th>Financial metric</th>'+data.years.map(y=>'<th>'+esc(y.label)+'<br><small>'+y.end+'</small></th>').join('')+'</tr></thead><tbody>'+rows.filter(([,k])=>data.years.some(y=>Number.isFinite(v(y,k)))&&(k!=='commonIncome'||data.years.some(y=>!Number.isFinite(v(y,'net'))&&Number.isFinite(v(y,k))))).map(([label,k])=>'<tr id="history-'+k+'" class="'+(['fcf','margin'].includes(k)?'calculated-row':'')+'"><td>'+label+(['fcf','margin'].includes(k)?' <span class="calculation-label">Calculated</span>':'')+'</td>'+data.years.map(y=>'<td>'+(k==='fcf'?num(fcf(y)===null?null:fcf(y)/1e9,3):k==='margin'?pct(Number.isFinite(v(y,'operating'))?v(y,'operating')/v(y,'revenue'):null):factCell(y,k))+'</td>').join('')+'</tr>').join('')+'</tbody>';
