 $('sliders').innerHTML=specs.map(([key,label,min,max,step])=>'<div class="slider-row"><label class="slider-label" for="input-'+key+'"><span>'+(key==='growth'&&assumptions.segmentModel?'Common category growth adjustment':key==='margin'&&assumptions.segmentModel?.useMargins?'Segment margin anchor':label)+'</span><output id="output-'+key+'">'+pct(key==='growth'&&assumptions.segmentModel?assumptions.growth-assumptions.segmentModel.growthAnchor:assumptions[key])+'</output></label><p class="input-context">'+forecastInputContext(key)+'</p><input type="'+(requiredJudgments.includes(key)?'number':'range')+'" id="input-'+key+'" min="'+(key==='margin'?Math.min(min,Math.floor(assumptions.margin*10)*10):min)+'" max="'+max+'" step="'+step+'" placeholder="Required" value="'+(!Number.isFinite(assumptions[key])?'':(key==='growth'&&assumptions.segmentModel?assumptions.growth-assumptions.segmentModel.growthAnchor:assumptions[key])*100)+'" data-key="'+key+'"></div>').join('');
