 $('sliders').querySelectorAll('input').forEach(input=>input.addEventListener('input',()=>{assumptions[input.dataset.key]=(input.value.trim()===''?NaN:Number(input.value)/100)+(input.dataset.key==='growth'&&assumptions.segmentModel?assumptions.segmentModel.growthAnchor:0);$('output-'+input.dataset.key).textContent=pct(input.dataset.key==='growth'&&assumptions.segmentModel?assumptions.growth-assumptions.segmentModel.growthAnchor:assumptions[input.dataset.key]);document.querySelectorAll('[data-scenario]').forEach(b=>b.classList.remove('selected'));updateModel();}));
