 renderCategoryPath();renderResearchSummary();renderModelSuitability();renderMarket();renderValuationEvidence();renderScenarioComparison();setValuationPanels(false);const missing=requiredJudgments.filter(k=>!Number.isFinite(assumptions[k]));
 if(missing.length&&!assessCompany(data).financial){const names={reinvest:'Net reinvestment / revenue',discount:'Discount rate (WACC)',terminal:'Terminal growth'};$('valuation').innerHTML='<div class="valuation-checklist"><b>Complete your valuation inputs</b><p>No scenario value is calculated until these judgments are supplied.</p><ul>'+requiredJudgments.map(k=>'<li>'+(missing.includes(k)?'○ ':'✓ ')+'<a href="#input-'+k+'">'+names[k]+'</a>'+(missing.includes(k)?' — required':' — entered')+'</li>').join('')+'</ul></div>';$('projection-table').innerHTML='';$('sensitivity-table').innerHTML='';$('equity-bridge').textContent='';$('comparison').textContent='';return;}
 let result;try{result=dcf(data,assumptions);}catch(e){$('valuation').innerHTML='<div class="error-model">'+esc(e.message)+'</div>';$('projection-table').innerHTML='';$('sensitivity-table').innerHTML='';$('comparison').textContent='';$('equity-bridge').textContent=assessCompany(data).financial?'Equity bridge withheld: a specialist valuation model is required.':'Bridge unavailable until the model inputs are valid.';return;}
 $('valuation').innerHTML='<div class="valuation-number">'+(result.perShare===null?'Unavailable':'$'+num(result.perShare,2))+'</div><div class="valuation-caption">'+(result.perShare===null?'Per-share value requires cash, debt, and share-count data.':'Illustrative scenario output · not an independently supported valuation')+'</div><div class="valuation-details"><div>Enterprise value<b>'+bn(result.ev)+'</b></div><div>Equity value<b>'+bn(result.equity)+'</b></div><div>Terminal value / enterprise value<b>'+pct(result.terminalShare)+'</b></div><div>Net borrowings less liquid assets<b>'+bn(result.debt===null?null:result.debt-result.cash-(data.years.at(-1).facts.investments?.val||0))+'</b></div></div>';
 setValuationPanels(true);renderEquityBridge(result);
 $('projection-table').innerHTML='<thead><tr><th>Operating model</th>'+result.rows.map(r=>'<th>FY '+r.year+'E</th>').join('')+'</tr></thead><tbody>'+[['Revenue','revenue'],['Operating income','operating'],['After-tax operating profit','nopat'],['Net reinvestment','reinvestment'],['Free cash flow to firm','fcff'],['Discounted FCFF','discounted']].map(([label,k])=>'<tr><td>'+label+'</td>'+result.rows.map(r=>'<td>'+num(r[k]/1e9)+'</td>').join('')+'</tr>').join('')+'</tbody>';
 const growths=[.01,.02,.025,.03,.04],rates=[-.02,-.01,0,.01,.02].map(delta=>assumptions.discount+delta);
