 enhanceHelp();
 const q=activeMarketQuote();$('comparison').textContent=q&&marketMetrics(data,q).scenarioEligible&&result.perShare!==null?'Scenario value / reference price: '+num(result.perShare/q.price,2)+'× · price dated '+q.asOf+'. This is an assumption-driven comparison, not a recommendation.':'';
