 const s=view.segments[businessSelection],prior=Number.isFinite(s.priorRevenue)&&s.priorRevenue>0?s.priorRevenue:null;
 $('business-detail').innerHTML='<span class="eyebrow">SELECTED CATEGORY</span><h3>'+esc(s.name)+'</h3><p>'+esc(s.description)+'</p><div class="business-detail-values"><div><span>Annual revenue</span><b>'+bn(s.revenue)+'</b></div></div>'+'<div class="business-driver"><span class="eyebrow">'+(p.method==='reviewed'?'OPERATING DRIVERS · FROM THE FILING':'OPERATING DRIVER COVERAGE')+'</span><p>'+esc(s.driver||'Operating-driver commentary has not been reviewed. Read the business and management discussion sections of the source filing.')+'</p></div><a href="'+esc(p.source)+'" target="_blank" rel="noopener">Read the annual report ↗</a>';
