function forecastInputContext(key){
 const c=forecastBasis;
 if(key==='margin'&&assumptions.segmentModel?.useMargins)return 'At the reported company margin anchor, each segment uses its own margin assumption. Moving this anchor shifts every segment margin by equal percentage points. The resulting weighted company margin is shown below.';
 if(key==='growth'&&assumptions.segmentModel)return 'Adds or subtracts the same number of percentage points from every category growth rate. Zero preserves the category inputs. Combined revenue growth is calculated in the category table.';
 const contexts={growth:(c.historyBased.growth?'History-based start: ':'Illustrative 10% start; usable history unavailable. Historical growth: ')+pct(c.growth)+' annualized, '+c.firstEnd+' to '+c.lastEnd+'.',margin:(c.historyBased.margin?'History-based start: ':'No usable reported operating margin. The 0% start is a placeholder; choose an explicit future margin to model profitability. Historical context: ')+pct(c.margin)+' median operating margin across '+c.marginCount+' of the last three annual periods.',tax:c.taxCount?'History-based start: '+pct(c.tax)+' median accounting tax rate from '+c.taxCount+' of the last three annual periods (positive pretax profit; rates from 0% to 50%). Future cash taxes may differ.':'Judgment input: 21% illustrative start. Suitable historical pretax profit and tax expense are unavailable.',reinvest:'Required judgment: enter net reinvestment as a percent of revenue. Latest gross cash asset spending was '+pct(c.capex)+' of revenue; latest selected reinvestment proxy: '+pct(reinvestmentHistory(data).at(-1)?.ratio)+'. Neither establishes future reinvestment. See the historical reinvestment panel for available components and missing items; its partial proxy does not set this assumption.',discount:'Required judgment: enter a discount rate. This report has not estimated WACC from financing costs and market risk.',terminal:'Required judgment: enter perpetual growth below the discount rate. Historical growth does not establish this value.'};
 return esc(contexts[key])+' <a href="#history">See financial history ↗</a>';
}
function renderScenarioComparison(){
 const c=forecastBasis,difference=assumptions.growth-c.growth;
 $('forecast-narrative').textContent=Number.isFinite(c.growth)?'Your current scenario assumes sales grow '+pct(assumptions.growth)+' annually, '+(Math.abs(difference)<.0005?'approximately matching':difference>0?'faster than':'more slowly than')+' the '+pct(c.growth)+' historical annualized rate. Historical performance does not predict future results.':'Historical sales growth is unavailable. Your current growth input is an assumption.';
 if(assumptions.segmentModel)$('forecast-narrative').textContent='Category mode: each business grows at its own assumed rate. Their revenue totals feed the valuation; '+(assumptions.segmentModel.useMargins?'segment-specific operating margins capture the changing business mix. Tax and reinvestment remain company-wide.':'company-wide margin, tax and reinvestment are held in common.')+'';
 $('scenario-growth-method').textContent=assumptions.segmentModel?'Every category growth rate minus 5 percentage points, current rates, and plus 5 points. Other inputs are fixed.':'Current growth input minus 5 percentage points, current input, and plus 5 points. Other inputs are fixed.';
 const variants=forecastVariants(assumptions),valid=[];
 $('scenario-comparison').innerHTML=variants.map(s=>{let r,error;try{r=dcf(data,s.inputs);if(r.perShare!==null)valid.push(r.perShare);}catch(e){error=e.message;}return '<article class="scenario-card"><span class="eyebrow">'+s.label+'</span><strong>'+(r?.perShare!=null?'$'+num(r.perShare,2):'Unavailable')+'</strong><span>Modeled value per share</span><p>'+(assumptions.segmentModel?num((s.inputs.growth-assumptions.segmentModel.growthAnchor)*100)+' percentage points applied to each category':pct(s.inputs.growth)+' annual sales growth')+'</p><small>'+esc(error||'All other inputs held at your current values.')+'</small></article>';}).join('');
 $('scenario-range').textContent=valid.length===3?'Growth-scenario range: $'+num(Math.min(...valid),2)+'–$'+num(Math.max(...valid),2)+' per share. This is not a probability or confidence interval.':'A complete per-share range is unavailable. Review the assumptions and missing balance-sheet data.';
}
function renderQuarters(){
 const q=data.quarterly,last=q?.quarters?.at(-1),prior=q?.comparison,ttm=q?.ttm;
 if(!last){$('quarter-freshness').textContent='Comparable quarterly facts are unavailable in this dataset. Annual history and valuation remain available.';$('quarter-kpis').innerHTML='';$('quarter-table').innerHTML='';$('quarter-analysis-table').innerHTML='';$('quarter-observations').textContent='No quarterly comparison can be calculated.';$('quarter-methodology').textContent='Import an original SEC company-facts file or analyze the ticker to retrieve updated data.';$('quarter-evidence').innerHTML='';return;}
 const value=(period,key)=>period?.facts?.[key]?.val,free=period=>Number.isFinite(value(period,'cfo'))&&Number.isFinite(value(period,'capex'))?value(period,'cfo')-value(period,'capex'):null;
 const filed=last.facts.revenue.sources.map(s=>s.filed).sort().at(-1),f=q.latestFiling;
 $('quarter-freshness').innerHTML=[['Latest supported quarter · may be reconstructed',last.start+' → '+last.end],['Supporting revenue filing',filed],['Latest revenue-bearing filing',f?f.form+' · '+f.filed:'Unavailable'],['Dataset retrieved',data.retrieved.slice(0,10)]].map(([label,text])=>'<div><span>'+label+'</span><b>'+esc(text)+'</b></div>').join('')+'<p>'+(last.end>data.years.at(-1).end?'Newer quarterly results are available beyond the annual valuation base. ':'The latest quarter ends with the annual valuation base. ')+'Retrieval date is not the financial period or filing date. Filing freshness refers to the company-facts revenue coverage; earnings releases or other filings may be newer.</p>';
 const change=(now,before)=>Number.isFinite(now)&&Number.isFinite(before)?before>0?(now/before-1>=0?'Up ':'Down ')+pct(Math.abs(now/before-1)):bn(now-before)+' change':'Comparison unavailable';
 const reported=reportedQuarterPeriods(q),reportedLast=reported.last,reportedPrior=reported.prior;
 const reportedMetrics=[['Revenue','revenue'],['Operating income','operating'],['Net income','net'],['Operating cash flow','cfo'],['Cash equipment purchases','capex']];
 $('quarter-kpis').innerHTML=reportedMetrics.filter(([,k])=>reportedLast?.facts[k]?.method==='reported').slice(0,4).map(([label,k])=>'<div class="kpi quarter-kpi"><div class="kpi-label">'+label+'</div><div class="kpi-value">'+bn(value(reportedLast,k))+'</div><a class="kpi-source" href="'+esc(reportedLast.facts[k].sources[0].url)+'" target="_blank" rel="noopener">Company-reported quarter ↗</a></div>').join('');
 const directCell=(period,key)=>{const f=period?.facts[key];return f?.method==='reported'?'<a href="'+esc(f.sources[0].url)+'" target="_blank" rel="noopener">'+num(f.val/1e9,3)+' ↗</a>':'—';};
 $('quarter-table').innerHTML='<thead><tr><th>Directly reported metric</th>'+[reportedLast,reportedPrior].map(q=>'<th>'+(q?esc(q.start)+' → '+esc(q.end):'Prior quarter unavailable')+'</th>').join('')+'</tr></thead><tbody>'+reportedMetrics.filter(([,k])=>[reportedLast,reportedPrior].some(q=>q?.facts[k]?.method==='reported')).map(([label,k])=>'<tr><td>'+label+'</td><td>'+directCell(reportedLast,k)+'</td><td>'+directCell(reportedPrior,k)+'</td></tr>').join('')+'</tbody>';
 if(reportedLast?.end!==last.end)$('quarter-freshness').innerHTML+='<p><b>Reported table:</b> '+(reportedLast?'Latest directly reported quarter ends '+esc(reportedLast.end)+'.':'No directly reported standalone quarter is available.')+' The newer '+esc(last.end)+' quarter is reconstructed and appears only in Calculated analysis.</p>';
 const metrics=[['Revenue','revenue'],['Operating income','operating'],['Operating margin','margin'],['Net income','net'],['Operating cash flow','cfo'],['Cash asset spending','capex'],['Free cash flow','fcf']];
 const columns=[last,prior,ttm],headers=['Latest quarter','Same quarter last year','Trailing 12 months'];
 function cell(period,key){if(!period)return '—';if(key==='fcf')return Number.isFinite(free(period))?num(free(period)/1e9)+' <small>calculated</small>':'—';if(key==='margin')return Number.isFinite(value(period,'operating'))&&value(period,'revenue')>0?pct(value(period,'operating')/value(period,'revenue')):'—';const fact=period.facts[key];return fact?num(fact.val/1e9)+' <a href="#quarter-evidence" class="quarter-source-link">'+(fact.method==='reported'?'reported':fact.method==='derived'?'derived':'4-quarter sum')+'</a>':'—';}
 $('quarter-analysis-table').innerHTML='<thead><tr><th>Financial metric</th>'+columns.map((period,i)=>'<th>'+headers[i]+'<br><small>'+(period?esc(period.start)+' → '+esc(period.end):'Unavailable')+'</small></th>').join('')+'</tr></thead><tbody>'+metrics.map(([label,key])=>'<tr><td>'+label+'</td>'+columns.map(period=>'<td>'+cell(period,key)+'</td>').join('')+'</tr>').join('')+'</tbody>';
 const bullets=[];
 if(prior){bullets.push('Quarterly sales: '+bn(value(prior,'revenue'))+' → '+bn(value(last,'revenue'))+'; '+change(value(last,'revenue'),value(prior,'revenue')).toLowerCase()+'.');const nowMargin=value(last,'revenue')>0&&Number.isFinite(value(last,'operating'))?value(last,'operating')/value(last,'revenue'):null,priorMargin=value(prior,'revenue')>0&&Number.isFinite(value(prior,'operating'))?value(prior,'operating')/value(prior,'revenue'):null;if(Number.isFinite(nowMargin)&&Number.isFinite(priorMargin))bullets.push('Operating margin: '+pct(priorMargin)+' → '+pct(nowMargin)+'. This is the share of sales left as operating profit.');if(Number.isFinite(free(last))&&Number.isFinite(free(prior)))bullets.push('Cash left after cash asset spending: '+bn(free(prior))+' → '+bn(free(last))+'. These figures alone do not explain the cause of the change.');}else bullets.push('A comparable same-quarter period is unavailable. No year-over-year change has been estimated.');
 bullets.push(ttm&&Number.isFinite(value(ttm,'revenue'))?'Trailing 12-month sales total '+bn(value(ttm,'revenue'))+' across four consecutive quarters, rather than multiplying one quarter by four.':ttm?'Four consecutive quarters are available, but trailing sales failed the annual reconciliation check and are withheld.':'Four consecutive comparable quarters are unavailable, so trailing totals are withheld.');
 $('quarter-observations').innerHTML=bullets.map(text=>'<p>'+esc(text)+'</p>').join('');
 $('quarter-methodology').innerHTML='<ul>'+q.notes.map(text=>'<li>'+esc(text)+'</li>').join('')+'</ul><p>Forecasts and DCF continue to use the annual base. TTM is historical context, not a separate valuation input.</p>';
 if(ttm?.reconciliation)$('quarter-methodology').innerHTML+='<p>'+Object.entries(ttm.reconciliation).map(([key,note])=>esc(key)+': '+esc(note)).join(' · ')+'</p>';
 $('quarter-evidence').innerHTML=q.quarters.slice(-8).reverse().map(period=>'<div class="quarter-evidence-block"><h4>Quarter '+esc(period.start)+' → '+esc(period.end)+'</h4>'+Object.entries(period.facts).filter(([,fact])=>fact).map(([key,fact])=>'<div><b>'+esc(metrics.find(row=>row[1]===key)?.[0]||key)+'</b><span>'+bn(fact.val)+' · '+(fact.method==='derived'?'cumulative total − prior cumulative total':'quarter-only reported fact')+(fact.crossFiling?' · combines different filings':'')+'</span>'+fact.sources.map(s=>'<a target="_blank" rel="noopener" href="'+esc(s.url)+'">'+esc(s.start)+' → '+esc(s.end)+' · '+bn(s.val)+' · '+esc(s.form)+' filed '+esc(s.filed)+' · '+esc(s.tag)+' ↗</a>').join('')+'</div>').join('')+'</div>').join('');
 $('quarter-analysis-table').querySelectorAll('.quarter-source-link').forEach(a=>a.addEventListener('click',()=>{$('quarter-evidence').closest('details').open=true;}));
}
