 $('strength-calculations').innerHTML=[['Long-term debt subtotal',bn(s.longDebtSubtotal),'Current + noncurrent carrying balances'],['Interest coverage proxy',s.coverage===null?'—':num(s.coverage)+'×','Operating income ÷ selected interest expense'],['Cash after selected uses',bn(s.remaining),'CFO − cash purchases − dividends − buybacks'],['Cash less next-12-month principal',bn(s.principalVsCash),'Only selected cash and principal disclosures']].map(([label,amount,formula])=>'<p><b>'+label+': '+amount+'</b><br>'+formula+'</p>').join('');
 const balanceRows=[['Cash & equivalents','cash'],['Short-term investments','investments'],['Long-term debt: current portion','debtCurrent'],['Long-term debt: noncurrent','debtLong'],['Short-term borrowings / commercial paper','shortDebt'],['Operating lease liability','operatingLeases'],['Finance lease liability','financeLeases']];
