 $('strength-balance').innerHTML='<tbody>'+balanceRows.filter(([,key])=>Number.isFinite(value(key))).map(([label,key])=>'<tr><td>'+label+'</td><td>'+factValue(key)+'</td></tr>').join('')+'</tbody>';
 const maximum=Math.max(1,...s.maturities.map(m=>Number.isFinite(m.value)?m.value:0));
