function renderSegmentProfits(view){
 const total=data.years.at(-1).facts.operating?.val,all=view.segments.every(s=>Number.isFinite(s.operatingIncome)),sum=all?view.segments.reduce((n,s)=>n+s.operatingIncome,0):null,agrees=all&&Number.isFinite(total)&&Math.abs(sum-total)<=Math.max(1,Math.abs(total)*.000001);
 $('segment-profits').innerHTML=all?'<div class="table-scroll"><table><thead><tr><th>Business</th><th>Reported revenue</th><th>Reported operating income</th></tr></thead><tbody>'+view.segments.map(s=>'<tr><td>'+esc(s.name)+'</td><td>'+bn(s.revenue)+'</td><td>'+bn(s.operatingIncome)+'</td></tr>').join('')+'</tbody></table></div><p class="small-note">Source: linked annual filing. '+(agrees?'Reported segment profits reconcile to company operating income.':'Corporate adjustments may remain; separate margin forecasting is withheld.')+'</p>':'<p class="small-note">Segment operating income has not been mapped for this view; no profit contribution is inferred.</p>';
 $('segment-calculations').innerHTML='<div class="table-scroll"><table><thead><tr><th>Business</th><th>Revenue share</th><th>Prior-period revenue growth</th><th>Operating margin</th><th>Share of company operating income</th></tr></thead><tbody>'+view.segments.map(s=>'<tr><td>'+esc(s.name)+'</td><td>'+pct(s.revenue/businessProfile.totalRevenue)+'</td><td>'+pct(s.priorRevenue>0?s.revenue/s.priorRevenue-1:null)+'</td><td>'+pct(Number.isFinite(s.operatingIncome)?s.operatingIncome/s.revenue:null)+'</td><td>'+pct(total>0&&Number.isFinite(s.operatingIncome)?s.operatingIncome/total:null)+'</td></tr>').join('')+'</tbody></table></div><p class="small-note">Shares, growth and margins above are calculated by this tool. Source: '+esc(view.label)+', annual period ended '+esc(businessProfile.periodEnd)+'.</p>';
}
